BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "tienda_categoria" ("id" varchar(64) NOT NULL PRIMARY KEY, "nombre" varchar(120) NOT NULL UNIQUE);
CREATE TABLE "tienda_cliente" ("id" varchar(64) NOT NULL PRIMARY KEY, "nombre" varchar(150) NOT NULL, "documento" varchar(50) NOT NULL, "telefono" varchar(50) NOT NULL, "correo" varchar(150) NOT NULL, "direccion" varchar(200) NOT NULL, "tipo" varchar(10) NOT NULL);
CREATE TABLE "tienda_compra" ("id" varchar(64) NOT NULL PRIMARY KEY, "fecha" datetime NOT NULL, "total" bigint NOT NULL, "creado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "proveedor_id" varchar(64) NOT NULL REFERENCES "tienda_proveedor" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_descuento" ("id" varchar(64) NOT NULL PRIMARY KEY, "nombre" varchar(120) NOT NULL UNIQUE, "tipo" varchar(20) NOT NULL, "valor" bigint NOT NULL, "disponible" bool NOT NULL);
CREATE TABLE "tienda_detallecompra" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_historico" varchar(150) NOT NULL, "costo_unitario" bigint NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "subtotal_linea" bigint NOT NULL, "compra_id" varchar(64) NOT NULL REFERENCES "tienda_compra" ("id") DEFERRABLE INITIALLY DEFERRED, "producto_id" varchar(64) NOT NULL REFERENCES "tienda_producto" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_detallereembolso" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_historico" varchar(150) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "retorna_inventario" bool NOT NULL, "monto_reembolsado" bigint NOT NULL, "detalle_venta_id" bigint NOT NULL REFERENCES "tienda_detalleventa" ("id") DEFERRABLE INITIALLY DEFERRED, "producto_id" varchar(64) NOT NULL REFERENCES "tienda_producto" ("id") DEFERRABLE INITIALLY DEFERRED, "reembolso_id" varchar(64) NOT NULL REFERENCES "tienda_reembolso" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_detalleventa" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_historico" varchar(150) NOT NULL, "precio_unitario" bigint NOT NULL, "costo_unitario" bigint NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "subtotal_linea" bigint NOT NULL, "producto_id" varchar(64) NOT NULL REFERENCES "tienda_producto" ("id") DEFERRABLE INITIALLY DEFERRED, "venta_id" varchar(64) NOT NULL REFERENCES "tienda_venta" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_faltante" ("id" varchar(64) NOT NULL PRIMARY KEY, "descripcion" varchar(150) NOT NULL, "nombre_normalizado" varchar(150) NOT NULL, "cantidad_solicitada" integer unsigned NOT NULL CHECK ("cantidad_solicitada" >= 0), "fecha" datetime NOT NULL, "tipo" varchar(20) NOT NULL, "estado" varchar(20) NOT NULL, "registrado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "producto_id" varchar(64) NULL REFERENCES "tienda_producto" ("id") DEFERRABLE INITIALLY DEFERRED, "proveedor_id" varchar(64) NULL REFERENCES "tienda_proveedor" ("id") DEFERRABLE INITIALLY DEFERRED, "notas" text NOT NULL);
CREATE TABLE "tienda_perfilusuario" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rol" varchar(20) NOT NULL, "usuario_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_producto" ("id" varchar(64) NOT NULL PRIMARY KEY, "codigo" varchar(50) NOT NULL, "nombre" varchar(150) NOT NULL, "precio" bigint NOT NULL, "costo" bigint NOT NULL, "seguimiento_inventario" bool NOT NULL, "stock" integer NOT NULL, "descripcion" text NOT NULL, "imagenes" varchar(255) NOT NULL, "categoria_id" varchar(64) NOT NULL REFERENCES "tienda_categoria" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_proveedor" ("id" varchar(64) NOT NULL PRIMARY KEY, "nombre" varchar(150) NOT NULL, "telefono" varchar(50) NOT NULL, "correo" varchar(150) NOT NULL, "tipo" varchar(10) NOT NULL, "documento" varchar(50) NOT NULL, "direccion" varchar(200) NOT NULL);
CREATE TABLE "tienda_reembolso" ("id" varchar(64) NOT NULL PRIMARY KEY, "fecha" datetime NOT NULL, "total_reembolsado" bigint NOT NULL, "usuario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "venta_id" varchar(64) NOT NULL REFERENCES "tienda_venta" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_venta" ("id" varchar(64) NOT NULL PRIMARY KEY, "fecha" datetime NOT NULL, "actualizado_en" datetime NOT NULL, "estado" varchar(20) NOT NULL, "metodo_pago" varchar(20) NOT NULL, "subtotal" bigint NOT NULL, "iva" bigint NOT NULL, "descuento_nombre_historico" varchar(120) NOT NULL, "descuento_tipo_historico" varchar(20) NOT NULL, "descuento_valor_historico" bigint NOT NULL, "monto_descuento" bigint NOT NULL, "total" bigint NOT NULL, "valor_recibido" bigint NOT NULL, "cambio" bigint NOT NULL, "corregida" bool NOT NULL, "fecha_correccion" datetime NULL, "cliente_id" varchar(64) NULL REFERENCES "tienda_cliente" ("id") DEFERRABLE INITIALLY DEFERRED, "corregida_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "creado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "descuento_id" varchar(64) NULL REFERENCES "tienda_descuento" ("id") DEFERRABLE INITIALLY DEFERRED);
